@Test
final void createSessionJournalIsIdempotentAndDefinitionBound() {
    try (HostStore store = createStore(Clock.fixed(NOW, ZoneOffset.UTC))) {
        HostStore.CreateSessionResult first = store.createSession(
                "create-1", "hash-a", "session-created", MODEL, "workspace", NOW);
        HostStore.CreateSessionResult retry = store.createSession(
                "create-1", "hash-a", "session-created", MODEL, "workspace", NOW.plusSeconds(1));
        assertEquals("session-created", first.sessionId());
        assertEquals(first.sessionId(), retry.sessionId());
        assertTrue(first.firstApplication());
        assertFalse(retry.firstApplication());
        JiException changedCommand = assertThrows(JiException.class, () -> store.createSession(
                "create-1", "hash-b", "session-created", MODEL, "workspace", NOW));
        assertEquals(ErrorCode.COMMAND_PAYLOAD_CONFLICT, changedCommand.error().code());
        JiException reusedSession = assertThrows(JiException.class, () -> store.createSession(
                "create-2", "hash-c", "session-created", MODEL, "different", NOW));
        assertEquals(ErrorCode.COMMAND_PAYLOAD_CONFLICT, reusedSession.error().code());
        assertEquals(1, store.list().size());
    }
}

